    /// <summary>
    /// Modify based on the user selected back order parameter and it will give an info
    /// </summary>
    /// <param name = "sender">form datasource</param>
    /// <param name = "e">Data field</param>
    [
        FormDataFieldEventHandler(formDataFieldStr(CustParameters, CustParameters, METAllowBackOrders), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")
    ]
    public static void METAllowBackOrders_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource      custParameters_ds   = sender.datasource();
        CustParameters      custParameters      = custParameters_ds.cursor();
        DialogButton        dialogButton;
        
        if (custParameters.METAllowBackOrders == NoYes::No)
        {
            dialogButton = Box::yesNo("@MET:METDisableMessage", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                custParameters.METAllowBackOrders = NoYes::Yes;
            }
            else
            {
                custParameters.METAllowBackOrders = NoYes::No;
            }
        }

        else if (custParameters.METAllowBackOrders == NoYes::Yes)
        {
            dialogButton = Box::yesNo("@MET:METActivateMessage", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                custParameters.METAllowBackOrders = NoYes::No;
            }
            else
            {
                custParameters.METAllowBackOrders = NoYes::Yes;
            }
        }
    }

    /// <summary>
    /// MPJ_27378_ EnhancementCustomerNumberGeneration
    /// Activate the Parameter values
    /// </summary>
    /// <param name="sender">form data source</param>
    /// <param name="e">Data field</param>
    [FormDataSourceEventHandler(formDataSourceStr(CustParameters, METCustParameters), FormDataSourceEventType::Activated),
         SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
    public static void METCustParameters_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        METCustParameters           metCustParameters   = sender.cursor();
        
        if(metCustParameters.CustomerNumbering == NoYes::Yes)
        {
            sender.object(fieldNum(METCustParameters, BusinessUnit)).enabled(true);
        }
        else
        {
            sender.object(fieldNum(METCustParameters, BusinessUnit)).enabled(false);
        }

        if(metCustParameters.BusinessUnit == NoYes::No)
        {
            sender.object(fieldNum(METCustParameters, NumberSequenceId)).enabled(true);
        }
        else
        {
            sender.object(fieldNum(METCustParameters, NumberSequenceId)).enabled(false);
        }
    }
